param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'method-parameter-info-identity-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$methods=[Collections.Generic.List[Reflection.MethodInfo]]::new();$flags=[Reflection.BindingFlags]'Public,Instance';$apiCalls=0
foreach($spec in $plan.interfaces){$type=[Type]::GetType($spec.type,$true,$false);$parameters=[type[]]@($spec.parameters|ForEach-Object {[Type]::GetType($_,$true,$false)});foreach($route in $plan.routes){for($pass=0;$pass -lt $plan.passes;$pass++){$method=switch($route){'name'{$type.GetMethod($spec.method)};'flags'{$type.GetMethod($spec.method,$flags)};'types'{$type.GetMethod($spec.method,$parameters)};'flags-types'{$type.GetMethod($spec.method,$flags,$null,$parameters,$null)};'methods'{$type.GetMethods($flags)[0]};'ignore-case'{$type.GetMethod($spec.method.ToUpperInvariant(),($flags -bor [Reflection.BindingFlags]::IgnoreCase))}};if($null -eq $method -or $method.Name -ne $spec.method){throw 'Unexpected lookup method'};$methods.Add($method);$apiCalls++}}}

function Units($text){if($null -eq $text){return '~'};return ([int[]][char[]][string]$text -join ',')}
$rows=[Collections.Generic.List[object]]::new();for($index=0;$index -lt $methods.Count;$index++){$method=$methods[$index];$first=$method.GetParameters();$second=$method.GetParameters();$stable=$true;$membersSame=$true;$metadata=[Collections.Generic.List[string]]::new();for($i=0;$i -lt $first.Length;$i++){$stable=$stable -and [object]::ReferenceEquals($first[$i],$second[$i]);$membersSame=$membersSame -and [object]::ReferenceEquals($first[$i].Member,$method);$metadata.Add(($first[$i].Position.ToString()+'|'+$first[$i].ParameterType.FullName+'|'+(Units $first[$i].Name)))};$saved=if($first.Length -gt 0){$first[0]}else{$null};if($first.Length -gt 0){$first[0]=$null};$third=$method.GetParameters();$defensive=$first.Length -eq 0 -or [object]::ReferenceEquals($saved,$third[0]);$return1=$method.ReturnParameter;$return2=$method.ReturnParameter;$apiCalls+=5;$rows.Add([ordered]@{index=$index;parameterCount=$second.Length;arraysSame=[object]::ReferenceEquals($first,$second);parameterIdentitiesStable=$stable;defensiveCopy=$defensive;membersSame=$membersSame;returnSame=[object]::ReferenceEquals($return1,$return2);returnMemberSame=[object]::ReferenceEquals($return1.Member,$method);returnPosition=$return1.Position;returnName=(Units $return1.Name);parameterMetadata=($metadata -join ';')})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();methodCount=$methods.Count;apiCalls=$apiCalls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS parameter identity: $apiCalls API calls"
